import{_ as p,c as e,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"益","description":"高島易斷 - 益","frontmatter":{"title":"益","description":"高島易斷 - 益"},"headers":[],"relativePath":"classics/takashima/042.md","filePath":"classics/takashima/042.md"}'),i={name:"classics/takashima/042.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="益" tabindex="-1">益 <a class="header-anchor" href="#益" aria-label="Permalink to “益”">​</a></h1><h2 id="益-1" tabindex="-1">益 <a class="header-anchor" href="#益-1" aria-label="Permalink to “益”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>益：利有攸往，利涉大川。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>“益”字，上從興，橫之則從水，《坎》為水，亦為大川。下從皿，《釋文》“益以增長為名，以宏裕為義”，增長宏裕，皆言其利益之普也。《震》為行，《巽》為利，故曰“利有攸往”。凡卦言“利涉大川”，有取《乾》，有取《坤》，有取《巽》，隨卦取象。《益》上卦為《巽》，變《巽》之下成《乾》，變《巽》之上成《坎》，得《乾》《坎》之氣；《巽》為風，風行最疾，波濤無阻，是以既曰“利有攸往”，又曰“利涉大川”也。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>風雷，益。君子以見善則遷，有過則改。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>風雷者，二氣之升降、進退、周旋以相損益者也。故《震》上《巽》下為《恆》，《象》曰“雷風恆”，《巽》上《震》下為《益》，《象》曰“風雷益”。象以風雷易其位，蓋以風雷相遇，天地之間，上下無常也。以方位言，《震》為卯，《巽》為辰巳，由《震》而《巽》，其行也順，故其為《益》也宏。君子法之，見人之善則屈己以從，見已有過，則返躬自訟。故遷善當如風之速，改過當如雷之勇，謂之“見善則遷，有過則改”。“見”、“有”二字，可以見人己之分界。王弼曰：“遷善改過，益莫大焉。”</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：迅雷烈風，正當運途振作之際，改舊換新，在此時也。</p><p>○　問戰徵：電逐風行，正可一鼓而平。</p><p>○　問營商：有利則貿易，無則改售，宜迅速，不宜遲緩。</p><p>○　問功名：風雷合《益》，大得志也。</p><p>○　問疾病：是肝木太盛之症，治宜損陽扶陰。</p><p>○　問婚姻：《震》男《巽》女，天然配合。</p><p>○　問家宅：此宅防有雷擊風摧之患，完者宜修葺之改作之，朽者宜改作之。</p><p>○　問訟事：返躬自省，怒息氣平，訟事自罷。</p><p>○　問失物：已經遷改變易，不可復得。</p><p>○　問六甲：單月男，雙月女。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>“大作”者，天子巡狩之事，所謂“春省耕而補不足，秋省斂而助不給”，其他祭告、賑貸、遷國，皆“大作”也。《震》為作，《巽》為利，《乾》為大，為元，《坤》為用，為厚，“厚事”，即“大作”。初居內卦之下，事之始也，王者舉大事，建大功，利益計夫恆久，規則定於首圖，故“利用為大作”。在初，其事與天下共為之，其《益》亦與天下共享之，斯下民樂事趨公，願效其勞，不以其事為上之事，直以其事為己之事也，故得“元吉，無咎”。《象傳》以“下不厚事”釋之，謂不以其事厚重而難為，乃以其事輕易而樂從，踴躍爭先，“吉無咎”焉。或雲《震》屬春，《巽》屬春夏之交，“大作”者，東作之事，《繫辭》所云“耒耜之利，以教天下，盡取諸益”。其說亦通。</p><h2 id="初九佔" tabindex="-1">初九佔 <a class="header-anchor" href="#初九佔" aria-label="Permalink to “初九佔”">​</a></h2><p>○　問時運：好運初交，可以與作大事，無不如意。吉。</p><p>○　問戰徵：兵隊初交，即可一戰以成大功，有吉無咎。</p><p>○　問營商：初次營業，資本既厚，經營亦大，可獲大利，且能悠久無咎。</p><p>○　問功名：可望大魁天下，大吉。</p><p>○　問家宅：此宅新造，屋宇寬大，大吉無咎。</p><p>○　問婚姻：大吉。</p><p>○　問訟事：此訟為公眾大事，非關一己私憤也。無咎。</p><p>○　問行人：在外正當謀事立業，一時未歸。</p><p>○　問六甲：生女。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>明治二十四年，佔秋收豐歉，筮得《益》之《觀》。</p><p>斷曰：此爻虞氏以“大作”為東作，即《繫辭》謂耒耜之利取諸益，與所佔秋收，爻象適合。爻辭曰“利用”，曰“元吉”，曰“無咎”，知收成必豐無歉。卦名曰《益》，卦體曰“益下”，年穀豐登，千倉萬箱，正如《彖傳》所云，“天施地生，其益無方”，吉莫大焉。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>“十朋之龜”，解同《損》五，《益》二之龜，即《損》五之龜也。《損》五以龜奉上，《益》二即以下所奉者，轉而益下。龜之益人，其靈爽足以世守，非在一時之吉也，故曰“永貞吉”。二居《震》之中，當位應《巽》，《震》為帝，為祭，故曰“王用享於帝”。“王”指九五，五用二之朋龜，告享於帝，以乞上祐，吉莫大焉。《郊·特牲》曰：“卜郊受命於祖廟，作電於禰宮官”，是為享帝用龜之事。《象傳》以“自外來”釋之，以《益》為內，《損》為外，龜自《損》來，故謂“外來”也。</p><h2 id="六二佔" tabindex="-1">六二佔 <a class="header-anchor" href="#六二佔" aria-label="Permalink to “六二佔”">​</a></h2><p>○　問時運：主得意外之財，且能世守，永吉。</p><p>○　問戰徵：古者行軍先卜，出師必禱，此爻均吉，其戰必克。“自外來也”，可由外而攻之也。</p><p>○　問營商：貝貨即貨幣也，“十”，數之盈也；“或益之”者，疑有神助也。營商得此爻，必獲厚利，永吉。</p><p>○　問功名：古者命相舉賢，皆從枚卜，既得吉兆，其顯可知，故曰永吉。</p><p>○　問疾病：禱之即愈。</p><p>○　問家宅：二至四為《坤》，《坤》為安，為土，有安宅之象。《坤》“利永貞”故曰，“永貞吉”。此宅可以久居也。</p><p>○　問婚姻：《震》《巽》為長男長女，卜鳳之兆，自昔稱祥，百年好合，故得永吉。</p><p>○　問六甲：生男。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>友人某來，請佔某富紳家政，筮得《益》之《中孚》。</p><p>斷曰：二爻處內卦之中，體柔當位，卦名曰《益》，已知伊家內政得當，有益無損也。《漢書·食貨志》雲：“人用莫如龜”，龜者貨貝；“十朋之龜”，“十”，盈數，富足之象。“或益之”者，不知誰為益之也。《象傳》曰“自外來也”，蓋謂其《益》有來自外者也。《正義》謂二居《益》用謙，物自外來，朋龜獻策，弗能違也，故曰永貞乃吉。享帝者，謂明靈降福，報告於天也，即《損》五所謂“上祐”，“上”，天也，“自天祐之，吉無不利”，其在斯乎？今佔某富紳家政，得此爻辭，知某富紳家風清正，內政修明，卜之而蓍龜呈祥，禱之而神明賜福。家道之盛，日進日益，蓋有應乎時，得乎天，可大可久，而未有艾也。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>六三以陰居陽，處《震》之極，是動而求益者也，故曰“益之”。下互《坤》，《坤》為用，為事，為死喪，故曰“用凶事”。《益》在於三，民信素著，不特處常為益，即處變亦為《益》。蓋《益》非私己，用適其時，志在拯兇，事得無咎，故曰“無咎”。三動體《家人》，《家人》上爻曰“有孚威如”，《震》為應，誠心相應，有威孚之象。三當內外卦之中，《震》又為行，故曰“有孚中行”。《震》為諸候，又為告，故曰“告公”。《周禮》，“珍圭以徵守，以恤凶荒”；毛氏西河雲，“凡王者憂兇之禮，出珍圭以致王命，使恤兇之地，或去其徵，或弛其政”，此即《益》下之“用凶事”者也。圭為符信，所以示信，以通上下之情也，故曰“告公用圭”。《象傳》以“固有之也”釋之，謂《益》“用凶事”，在民若第知為益，而不知為兇，以為其事為固有之也。夫《益》而至於“用凶事”，斯真其益之無方矣；。凶事而若“固有之”，愈見民悅之無疆矣。初爻《象傳》曰，“下不厚事”，意亦相同。</p><h2 id="六三佔" tabindex="-1">六三佔 <a class="header-anchor" href="#六三佔" aria-label="Permalink to “六三佔”">​</a></h2><p>○　問時運：運途多歉，以其素行誠實，人皆信之，可以無咎。</p><p>○　問戰徵：兵本凶事，又陷危地，幸眾軍同心戮力，得奔告大營，獲救出險，無咎。</p><p>○　問功名：先苦後甘，先難後獲。</p><p>○　問營商：諺雲“欲求富，走險路”。</p><p>○　問家宅：此宅多兇，惟有中行之德，斯能逢凶化吉。</p><p>○　問婚姻：恐從喪服中成親，然無咎也。</p><p>○　問訟事：須訴之上官，乃得準信，罷訟。</p><p>○　問失物：恐涉詞訟。</p><p>○　問六甲：生男。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>友人某來，請佔氣運，筮得《益》之《家人》。</p><p>斷曰：爻辭曰益用凶事，是能極兇濟危，為《益》之至難至急者也。曰“有孚中行，告公用圭”，是必所益之事，得中行之道，可見信於人，即告諸上官而無不允行也。今足下佔氣運，而得此爻，知足下有過於求益之心，一涉私己，咎有難免，幸而志在救兇，素行中正，又能實心辦事，可以無咎。此皆就爻象而論也。近聞足下設立移民會社，於西亞米利加地方，收買土地，創辦開墾牧畜之業，使無產之徒，各就其業，爻辭所云“益之用凶事”者，蓋指此也。邇來貧民信之，紛紛遷徒出外，即爻辭所謂“有孚中行”也。政府以足下創此拯兇濟危之大業，為之賞譽嘉獎，即爻辭所謂“告公用圭”之義也。至四爻曰“從，利用為依遷國”，其辭愈明。五爻曰“有孚惠心”，其德愈新。《象傳》曰“大得志也”，正足下得志之時也。</p><p>明治二十五年四月，餘就任北海道炭礦鐵道會社長，一次巡行鐵道礦山，地當嚴冷，凍雪未消，一時胃寒罹疾，止宿札幌旅店，就札幌病院長診察，發熱超四十度。翌朝約將入院，因之一筮，得《益》之《家人》。</p><p>斷曰：此卦名曰《益》，《益》之為言增也，於病亦然。爻曰“益之用凶事，”在病恐愈增兇也。至翌日則當四爻，四爻有“利用”“遷國”之辭。餘篤《易》佔，決計帶疾發程，遂告病院長，請給藥劑，院長止而不聽，即夜自小樽搭汽船，翌朝至函館。忽得札幌來電，報昨夜札幌市中失火，餘所止宿旅店，已被回祿，乃知《易》機所云，有不在病，而在火者，其神妙誠不可測也。時札幌新聞社所論，謂餘舉動，有預知有火而去者，然餘因病而佔，就病論病，第知為兇，猶幸無咎，故得力疾而行，並未嘗推測火災，今災後推繹，乃知變卦為《離》，《離》為火也。</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>四居《巽》之始，與初相應，與三相比。初曰“利用”，故四亦曰“利用”；初曰“為大作”，四之“遷國”，即“大作”之事也。三曰“中行”，曰“告公”，故四亦曰“中行告公”，三四皆當內外卦之中，故皆為中行。“告”，指三，“公”，指四，以四為《益》主爻，三欲益下，恐四阻之，是以告於四也。“公從”者，四從之也，上互《艮》，《艮》為社稷，下互《坤》，《坤》為國邑，《震》為奔走，《巽》為進退，皆有遷之象，故曰“遷國”。卦體本為《乾》《坤》《否》，《否》五爻曰，“其亡其亡，繫於苞桑”，有國難之憂焉；《否》《象傳》曰“儉德闢難”，有遁避之意焉；《否》變而為《益》，故利用遷國。《左傳》隱公五年，《傳》曰“我國之東遷，晉鄭焉依？”盤庚曰：“視民利用遷”，皆以遷為益者也。《象傳》以“益志”釋之，謂四從而遷之，四之志，惟在《益》下也。按《震》為東方，《巽》為東南，《易》當殷周之際，“遷國”者，指太公遷歧而言，岐屬殷西南，為《坤》方，是明證也。</p><h2 id="六四佔" tabindex="-1">六四佔 <a class="header-anchor" href="#六四佔" aria-label="Permalink to “六四佔”">​</a></h2><p>○　問時運：目下有難，宜擇善地暫避。</p><p>○　問戰徵：宜退兵移營，急請救援。</p><p>○　問營商：宜稟告店主，改遷別地，另開市面。</p><p>○　問家宅：宜遷居。</p><p>○　問功名：不成，須改就別業。</p><p>○　問婚姻：須別尋媒妁。</p><p>○　問失物：不得。</p><p>○　問六甲：生女。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>友人來請佔某貴顯氣運，筮得《益》之《無妄》。</p><p>斷曰：卦象為損上益下，爻象為動眾遷國，某貴顯身任當道，為國為民，正合此象。我國寰海平定，固無盤庚遷殷，太公遷岐之事，惟近來為開拓北海道地面，使內民移住。天皇陛下議就北海道建築行宮，為避暑計，爻辭所云利用遷國，意者其在此乎？且聞移民之議，某貴顯實主其事，爻所云“中行告公”，謂某貴顯秉中行之德，創利用之謀，進告於天皇，得以允從而行也。此為國家開化之盛業，即可卜貴顯運命之盛行也已。友人大喜曰：爻辭精切的當，誠吉事之佔也，當速回告某貴顯。匆匆辭去。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>五爻剛健中正，得位居尊，為《益》之主。以惠為益，其益越大，以心行惠，其惠愈宏，是以實心行實惠，心無盡，惠亦無盡，故謂“有孚惠心”。自初爻以來，凡巡狩、祭告、賑災、遷國，無一非惠民之事，即無一非惠民之心，所謂“乾元以美利利天下”者，即此心也。事之《益》，其吉待問，心之惠，其吉不待問矣，故謂之“勿問元吉”。信惠之施於下者，在我為心，下之受此信惠者，目之為德；九五得《坤》氣，《坤》為我，故謂之“有孚惠我德”。“問”，問卜也，古者舉大事，必卜之，以決吉凶。以惠行政，勿疑何卜？“元吉”，即從初爻“元吉，無咎”來，上以孚惠下，下即以孚德上，下上交孚，上益下而上亦受其益也。《象傳》以“大得志”釋之，謂本此惠心，行此惠政，天下皆受我德惠，而中心誠服，正可得志而有為也，故曰“大得志也”。</p><h2 id="九五佔" tabindex="-1">九五佔 <a class="header-anchor" href="#九五佔" aria-label="Permalink to “九五佔”">​</a></h2><p>○　問時運：“心好無歹運”，以仁存心，事無不吉，不待問也。</p><p>○　問營商：以義為利，誠實相交，利益與共，以此為商，利益廣矣。</p><p>○　問功名：實至名歸，大吉。</p><p>○　問戰徵：罰必信，賞必公，戰無不克，大吉。</p><p>○　問家宅：此為仁裡德門，勿問而知為善人之室也，大吉。</p><p>○　問婚姻：非親即友，必是舊交，“勿問元吉”。</p><p>○　問六甲：生女。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>友人某來曰：欲以某氏子為養嗣，佔前途吉凶。筮得《益》之《頤》。</p><p>斷曰：九五《坎》爻，《坎》為孚，為心，為美，亦為後，故爻辭曰“有孚惠心”。美，即吉也，為後者，適合足下養嗣之佔也。卦以損上益下為《益》，就嗣論，《益》在損父益子。“有孚惠心”，是父以誠實之心，授惠於子，子必樂為其子，不待問而知其吉也。子既受父之惠，當必有以報父之德，將承父之業，繼父之緒，必興父之宗，故曰“有孚惠我德”。《詩》所云“為他人子，為他人子”，可不必詠也。</p><p>明治二十八年，佔我國與清國交際，筮得《益》之《頤》。</p><p>斷曰：此卦內卦為雷，其性動，外卦為風，其性順；內卦屬我，外卦屬清，即可見兩國之動靜矣。卦名曰《益》，知兩國必互受其益。爻居九五，應在六二，二內，五外，亦當以二屬我，以五屬清。二爻曰：“或益之十朋之龜，弗克違，永貞吉”，在我國得此十朋之益者，即清之償款是也。“永貞吉”者，謂其吉不徒在一時也。五爻曰，“有孚惠心，勿問元吉。有孚惠我德”，謂清與我國，從此議和以後，不問而知其元吉。論歐洲各國，虎視耽耽，惟圖損清而益己，或侵其地，或奪其利。在清固守舊政，不知改圖，其為外邦所損削者，亦不知凡幾矣。而我與清幅員相鄰，當思有利共享，有益共受，以共保此東海之國也。《象傳》曰，“大得志也”，不為歐西各國所輕視也。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>上九，陽剛居外卦之極，是求益而過甚者也，太過則變，變則不為益而為擊矣。聖人觀象設卦，以“損上益下”為《益》，其心本偏在厚下，至上九，為上之益下者已多，轉而責下之益上，非待“莫益之，”夫且“或擊之”。“或”者眾而未定之辭。上動體為《屯》，“屯其膏”，即“莫益之”之謂也；反卦《損》，《損》上為《艮》，《艮》為手，故稱“擊”也。《巽》為進退，為不果，是無《恆》也；上動為《坎》；《坎》為心，本以《益》下之心，易而為《益》上之心，是無《恆》也。旁通為《恆》，《恆》上曰“振恆，兇”，振恆致敗於垂成，無《恆》不可以持久，故皆兇也。《象傳》所云“偏辭”者，謂其心之偏而不公也。“外來”者，謂其擊之出於意外也。</p><h2 id="上九佔" tabindex="-1">上九佔 <a class="header-anchor" href="#上九佔" aria-label="Permalink to “上九佔”">​</a></h2><p>○　問時運：好運已退，貪心過甚，防有意外之禍。</p><p>○　問戰徵：不待添兵加餉，即可進擊。</p><p>○　問營商：專求利己，所謂不奪不厭，必啟爭端，兇。</p><p>○　問功名：奪人之功以為名，其名必不久也，兇。</p><p>○　問家宅：此宅地位太高，有害無利，不可久居。</p><p>○　問婚姻：恐不能偕老。</p><p>○　問訟事：訟事無恆，轉兇為吉。</p><p>○　問行人：防中途有盜劫之患，兇。</p><p>○　問失物：或已打破，不可得也。</p><p>○　問六甲：生女。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>友人某來，請佔氣運，筮得《益》之《屯》。</p><p>斷曰：卦名曰《益》，本有大得利益之象。今佔得上爻，上爻居《益》之極，物極則變，恐非特無益，且有損傷之患。爻辭曰“莫益之”，是無益也；曰“或擊之”，是被傷也；曰“立心無恆”，謂人心不測，反手為雨，覆手心雲，防有意外之變也；終之曰“兇”，明言其佔之不吉也。爻象如是，足下當有戒焉。友人聞之，頗為心憂。後據所聞，此友一日至某家，商借千金，適某家藏金無為多，僅借得五百元，懷之而歸。途過某友家，告以其故，曰今因商要用款，約需千元，頃向某氏，貨得其半，復欲向君假取，以足其數。此友即以囊乏餘金婉辭，不知此友近遭破落，知其攜有巨金，忽生不良，伺其歸途，乘間襲擊，奪其金而去，某氏失金，又被重傷。日後此友就縛，始知奪金者，即為此友，倍感《易》理先示其兆也。</p><p>明治二十六年某月，受親友雨宮敬次郎之囑，佔銀貨漲落之結局，筮得《益》之《屯》。</p><p>斷曰：此卦下卦為《震》，《震》為玄黃，上卦為《巽》，《巽》為白色，白色銀，黃色金也。卦象《巽》上《震》下，是為銀高金落，可知銀之出產，多量於金也。爻辭曰：“莫益之，或擊之。立心勿恆，兇。”“莫益之”者，為價不再漲；“或擊之”者，謂價必損減“或”者，將然之辭；“勿恆”者，謂時價無定也。上爻變而為《屯》，《屯》者，難也。銀貨下落，市面皆受困難，必待出《益》入夬，夬者決也，將決去其弊，使銀貨時價，再得復舊也。若第以紙幣充行，恐未可永久繼續也。</p>',114)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
